<script setup>
import MButton from '../../../components/mds/MButton.vue'; import MEmptyState from '../../../components/mds/MEmptyState.vue'; import MTag from '../../../components/mds/MTag.vue';
defineProps({ upcoming: { type: Array, default: () => [] }, rows: { type: Array, default: () => [] }, days: { type: Number, default: 120 }, canCreate: Boolean, canEdit: Boolean, canDelete: Boolean }); const emit = defineEmits(['create', 'edit', 'delete']);
function countdown(row) { return row.daysUntil === 0 ? 'Hôm nay' : row.daysUntil === 1 ? 'Còn 1 ngày' : row.daysUntil == null ? 'Chưa xác định' : `Còn ${row.daysUntil} ngày`; }
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><div class="mx-auto max-w-[1200px] space-y-4"><header class="flex flex-wrap items-start justify-between gap-3 rounded-lg bg-[var(--mds-bg)] px-5 py-4 shadow-[var(--mds-shadow-card)]"><div><h1 class="text-[20px] font-semibold leading-7">Lịch nhắc</h1><p class="mt-1 text-[13px] leading-[18px] text-[var(--mds-text-secondary)]">Theo dõi mốc chăm sóc đối tác; lịch gửi và quyền ghi nhận do máy chủ kiểm soát.</p></div><MButton v-if="canCreate" variant="primary" @click="emit('create')">Thêm ngày nhắc</MButton></header><section class="rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]"><header class="border-b border-[var(--mds-border-light)] px-5 py-3"><h2 class="text-[16px] font-semibold">Sắp diễn ra</h2><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Trong {{ days }} ngày tới</p></header><div v-if="upcoming.length" class="grid gap-px bg-[var(--mds-border-light)] sm:grid-cols-2 lg:grid-cols-3"><article v-for="row in upcoming" :key="row.id" class="bg-[var(--mds-bg)] p-4"><div class="flex items-start justify-between gap-3"><strong class="min-w-0 text-[14px] leading-5">{{ row.title }}</strong><MTag :color="row.daysUntil != null && row.daysUntil <= row.leadDays ? 'warning' : 'neutral'">{{ countdown(row) }}</MTag></div><p class="mt-2 text-[13px] text-[var(--mds-text-secondary)]">{{ row.occurDate }}<span v-if="row.subjectName"> · {{ row.subjectName }}</span></p></article></div><MEmptyState v-else title="Chưa có lịch sắp diễn ra" description="Các mốc trong phạm vi đã chọn sẽ xuất hiện tại đây." /></section><section class="overflow-hidden rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]"><header class="border-b border-[var(--mds-border-light)] px-5 py-3"><h2 class="text-[16px] font-semibold">Tất cả ngày nhắc</h2></header><div v-if="rows.length" class="overflow-x-auto"><table class="w-full min-w-[780px] text-left text-[13px]"><thead class="bg-[var(--mds-bg-page)] text-[12px] text-[var(--mds-text-secondary)]"><tr><th class="px-5 py-3">Tiêu đề</th><th class="px-3 py-3">Loại</th><th class="px-3 py-3">Ngày</th><th class="px-3 py-3">Lặp</th><th class="px-3 py-3">Báo trước</th><th class="px-3 py-3">Đối tượng</th><th v-if="canEdit || canDelete" class="px-5 py-3"><span class="sr-only">Thao tác</span></th></tr></thead><tbody class="divide-y divide-[var(--mds-border-light)]"><tr v-for="row in rows" :key="row.id"><td class="max-w-[300px] px-5 py-3"><strong class="block">{{ row.title }}</strong><span v-if="row.note" class="mt-1 block truncate text-[12px] text-[var(--mds-text-secondary)]">{{ row.note }}</span></td><td class="px-3 py-3"><MTag color="neutral">{{ row.dateTypeLabel }}</MTag></td><td class="px-3 py-3">{{ row.eventDate }}</td><td class="px-3 py-3">{{ row.recurring ? 'Hằng năm' : 'Một lần' }}</td><td class="px-3 py-3">{{ row.leadDays }} ngày</td><td class="px-3 py-3">{{ row.subjectName || '—' }}</td><td v-if="canEdit || canDelete" class="whitespace-nowrap px-5 py-3 text-right"><MButton v-if="canEdit" variant="link" @click="emit('edit', row)">Sửa</MButton><MButton v-if="canDelete" variant="link" class="ml-2 text-[var(--mds-danger)]" @click="emit('delete', row)">Xóa</MButton></td></tr></tbody></table></div><MEmptyState v-else title="Chưa có ngày nhắc" description="Thêm lịch khi bạn cần theo dõi một mốc chăm sóc." /></section></div></section></template>
